(3105669, 436629, 69478, '<td valign="top">:) I love this image.</td>', ':) I love this image.', '2006-12-11 05:26:34.000000', NULL, 1),
(3105670, 436153, 69478, '<td valign="top">A little jouyous smile would make this pic a winner. I like this one with all the colors and DIRT.</td>', 'A little jouyous smile would make this pic a winner. I like this one with all the colors and DIRT.', '2006-12-11 05:27:20.000000', NULL, 1),
(3105672, 437011, 69478, '<td valign="top">Excellent concept and excecution. My eyes want to see a little of the top though, maybe thats the strength.</td>', 'Excellent concept and excecution. My eyes want to see a little of the top though, maybe thats the strength.', '2006-12-11 05:28:15.000000', NULL, 1),
(3105673, 437020, 69478, '<td valign="top">I love the concept. This was one of the ideas I also thought of using. Better than what I thought!! How about a real spect of dirt (maybe on the UV filter and not on the lens)</td>', 'I love the concept. This was one of the ideas I also thought of using. Better than what I thought!! How about a real spect of dirt (maybe on the UV filter and not on the lens)', '2006-12-11 05:30:20.000000', NULL, 1),
(3105674, 436067, 69478, '<td valign="top">:) great. Could not be more dirty!!</td>', ':) great. Could not be more dirty!!', '2006-12-11 05:31:10.000000', NULL, 1),
(3105675, 435969, 56400, '<td valign="top">I like this shot, the only problem I see is the back of the thumb is a little too dark. If it had been an inch or so back further it would have evened the shadow out more.</td>', 'I like this shot, the only problem I see is the back of the thumb is a little too dark. If it had been an inch or so back further it would have evened the shadow out more.', '2006-12-11 05:31:56.000000', NULL, 1),
(3105676, 436739, 69478, '<td valign="top">Excellent concept. How abt some variety in placements.</td>', 'Excellent concept. How abt some variety in placements.', '2006-12-11 05:32:14.000000', NULL, 1),
(3105677, 436984, 18219, '<td valign="top">I like the title.<br/>and the model!<br/>but i just think that if the location had been different, then it would make a lot of difference.<br/>Actually being in a house/bedroom/office or something rather than a "cold" hall way.<br/>otherwise, not bad!</td>', 'I like the title.and the model!but i just think that if the location had been different, then it would make a lot of difference.Actually being in a house/bedroom/office or something rather than a "cold" hall way.otherwise, not bad!', '2006-12-11 05:32:28.000000', NULL, 1),
(3105679, 437087, 69478, '<td valign="top">Excellent image</td>', 'Excellent image', '2006-12-11 05:32:59.000000', NULL, 1),
(3105680, 436290, 18219, '<td valign="top">very funny :-)<br/>my only suggestion for an improbvement would be to have more dirt on the floor.<br/>Apart from that, excellent attempt.<br/>Good luck.</td>', 'very funny :-)my only suggestion for an improbvement would be to have more dirt on the floor.Apart from that, excellent attempt.Good luck.', '2006-12-11 05:33:29.000000', NULL, 1),
(3105681, 436791, 69478, '<td valign="top">I would love to have the worms :) (In focus). a little bit more of DOF would be essential to make this one of the best.</td>', 'I would love to have the worms :) (In focus). a little bit more of DOF would be essential to make this one of the best.', '2006-12-11 05:34:10.000000', NULL, 1),
(3105682, 436350, 69478, '<td valign="top">I cant think of a thing that makes this better..</td>', 'I cant think of a thing that makes this better..', '2006-12-11 05:36:28.000000', NULL, 1),
(3105683, 436964, 69478, '<td valign="top">:) now thats a lot of work. Excellent lighting. would be happy to know more on this.</td>', ':) now thats a lot of work. Excellent lighting. would be happy to know more on this.', '2006-12-11 05:37:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3105684, 435414, 69478, '<td valign="top">I love the effect.</td>', 'I love the effect.', '2006-12-11 05:38:54.000000', NULL, 1),
(3105692, 435652, 48954, '<td valign="top">librodo? Ribbon i think.</td>', 'librodo? Ribbon i think.', '2006-12-11 05:58:24.000000', NULL, 1),
(3105715, 436789, 27845, '<td valign="top">I gave the other entries a quick browse, there''s only two which could compete with yours, so you''ll get a ribbon for sure. As Keith said, your turn this week. Good luck.</td>', 'I gave the other entries a quick browse, there''s only two which could compete with yours, so you''ll get a ribbon for sure. As Keith said, your turn this week. Good luck.', '2006-12-11 06:26:58.000000', NULL, 1),
(3105717, 436916, 61191, '<td valign="top">Oh, this is a strong shot: love the atmosphere and the story your shot tells. Great job!</td>', 'Oh, this is a strong shot: love the atmosphere and the story your shot tells. Great job!', '2006-12-11 06:30:30.000000', NULL, 1),
(3105721, 437117, 61191, '<td valign="top">Looks a bit surreal with the red something on the left - nice!</td>', 'Looks a bit surreal with the red something on the left - nice!', '2006-12-11 06:33:42.000000', NULL, 1),
(3105722, 437095, 61191, '<td valign="top">What is this? Sand? Very interesting texture.</td>', 'What is this? Sand? Very interesting texture.', '2006-12-11 06:34:26.000000', NULL, 1),
(3105724, 436681, 65886, '<td valign="top">excellent portrait!!</td>', 'excellent portrait!!', '2006-12-11 06:37:02.000000', NULL, 1),
(3105725, 436028, 69478, '<td valign="top">I like the positioning, and the composition. This image looks sad</td>', 'I like the positioning, and the composition. This image looks sad', '2006-12-11 06:38:32.000000', NULL, 1),
(3105726, 436984, 61191, '<td valign="top">Hehe, I''ve got something to clean up here will she come to help me? ;) Interesting take on the challenge, I like it. Perhaps the wall is too rough and cold: she would fit perfect into a living room cleaning things with a feather duster. Lighting is great. Prepare for 1000''s of views during voting! :)</td>', 'Hehe, I''ve got something to clean up here will she come to help me? ;) Interesting take on the challenge, I like it. Perhaps the wall is too rough and cold: she would fit perfect into a living room cleaning things with a feather duster. Lighting is great. Prepare for 1000''s of views during voting! :)', '2006-12-11 06:38:43.000000', NULL, 1),
(3105727, 434696, 61191, '<td valign="top">Nice grainy shot! Like the colors and mood here.</td>', 'Nice grainy shot! Like the colors and mood here.', '2006-12-11 06:39:12.000000', NULL, 1),
(3105728, 436263, 61191, '<td valign="top">Oh yes, that is dirty! :) Perfect processing, great job! Only thing that bugs me and prevents me from giving a 10: The pig should be horizontally centered.</td>', 'Oh yes, that is dirty! :) Perfect processing, great job! Only thing that bugs me and prevents me from giving a 10: The pig should be horizontally centered.', '2006-12-11 06:41:41.000000', NULL, 1),
(3105732, 436122, 61191, '<td valign="top">Awesome! Excellent idea, great execution.</td>', 'Awesome! Excellent idea, great execution.', '2006-12-11 06:43:18.000000', NULL, 1),
(3105735, 435548, 61191, '<td valign="top">Nice contrast between the dirty hands and the clean blue eyes. Great shot!</td>', 'Nice contrast between the dirty hands and the clean blue eyes. Great shot!', '2006-12-11 06:43:56.000000', NULL, 1),
(3105738, 436906, 61191, '<td valign="top">Hmm... these are 2 shots, right? I think you will get DQed for this, sorry :( However you idea is nice.</td>', 'Hmm... these are 2 shots, right? I think you will get DQed for this, sorry :( However you idea is nice.', '2006-12-11 06:45:35.000000', NULL, 1),
(3105740, 437116, 61191, '<td valign="top">Hehe, that''s funny!</td>', 'Hehe, that''s funny!', '2006-12-11 06:45:53.000000', NULL, 1),
(3105744, 436153, 53572, '<td valign="top">amazing, kita''s even pretty when grubby.  very nice shot, although i think the crop might have been better leaving out the decorations on the shirt - they''re a little distracting</td>', 'amazing, kita''s even pretty when grubby.  very nice shot, although i think the crop might have been better leaving out the decorations on the shirt - they''re a little distracting', '2006-12-11 06:46:45.000000', NULL, 1),
(3105746, 437010, 53572, '<td valign="top">very, very clever.</td>', 'very, very clever.', '2006-12-11 06:47:32.000000', NULL, 1),
(3105750, 436964, 53572, '<td valign="top">very nice shot.  well toned and composed.  i''m not sure if it woud have been improved with straightening.  those bath crayons are great, aren''t they?</td>', 'very nice shot.  well toned and composed.  i''m not sure if it woud have been improved with straightening.  those bath crayons are great, aren''t they?', '2006-12-11 06:49:18.000000', NULL, 1),
(3105763, 436350, 49109, '<td valign="top">great expression, good color</td>', 'great expression, good color', '2006-12-11 06:59:26.000000', NULL, 1),
(3105764, 436791, 49109, '<td valign="top">mmmmh, delicious! You are a born food-stylist!</td>', 'mmmmh, delicious! You are a born food-stylist!', '2006-12-11 06:59:34.000000', NULL, 1),
(3105765, 436949, 49109, '<td valign="top">I bet I know whose grandma that is... good work</td>', 'I bet I know whose grandma that is... good work', '2006-12-11 06:59:42.000000', NULL, 1),
(3105852, 436791, 43774, '<td valign="top">What a great setup!! I wish the bowl of worms were more in focus, I wouldn''t have known what it was if it weren''t for your title.</td>', 'What a great setup!! I wish the bowl of worms were more in focus, I wouldn''t have known what it was if it weren''t for your title.', '2006-12-11 08:41:40.000000', NULL, 1),
(3105853, 436828, 43774, '<td valign="top">Love the perspective here</td>', 'Love the perspective here', '2006-12-11 08:41:56.000000', NULL, 1),
(3105859, 434805, 43774, '<td valign="top">Wonderful abstract</td>', 'Wonderful abstract', '2006-12-11 08:47:35.000000', NULL, 1),
(3105868, 437005, 35229, '<td valign="top">This is the winner I say.</td>', 'This is the winner I say.', '2006-12-11 08:53:37.000000', NULL, 1),
(3105876, 435969, 15711, '<td valign="top">Very clever.  I think I know who did this too. (;~p)  9</td>', 'Very clever.  I think I know who did this too. (;~p)  9', '2006-12-11 08:57:36.000000', NULL, 1),
(3105878, 436974, 15711, '<td valign="top">Something about this makes me chuckle.  All those birds gathered together. The hint of red really works with all of the otherwise gray tones.</td>', 'Something about this makes me chuckle.  All those birds gathered together. The hint of red really works with all of the otherwise gray tones.', '2006-12-11 08:59:55.000000', NULL, 1),
(3105880, 436903, 15711, '<td valign="top">I envisioned something like this.  Nicely executed.  Great detail. I''m such a geek - I''d like it better if it had a cool title, but that''s just me. No points deducted because it doesn''t. 8</td>', 'I envisioned something like this.  Nicely executed.  Great detail. I''m such a geek - I''d like it better if it had a cool title, but that''s just me. No points deducted because it doesn''t. 8', '2006-12-11 09:00:38.000000', NULL, 1),
(3105881, 436403, 15711, '<td valign="top">I like the "off" balance of it.  Why on earth are there chairs scattered about?  Makes for interesting questions as to why and what. 7</td>', 'I like the "off" balance of it.  Why on earth are there chairs scattered about?  Makes for interesting questions as to why and what. 7', '2006-12-11 09:01:42.000000', NULL, 1),
(3105882, 437010, 15711, '<td valign="top">ROFL  now THAT''s original.</td>', 'ROFL  now THAT''s original.', '2006-12-11 09:02:05.000000', NULL, 1),
(3105888, 437087, 15711, '<td valign="top">I love this.  It''s simple and has a beautiful pop of golden yellow.  The DOF is awesome as is the diagonal line. 8</td>', 'I love this.  It''s simple and has a beautiful pop of golden yellow.  The DOF is awesome as is the diagonal line. 8', '2006-12-11 09:03:54.000000', NULL, 1),
(3105889, 436867, 68467, '<td valign="top">Nice colors - very nice frame too - well done</td>', 'Nice colors - very nice frame too - well done', '2006-12-11 09:03:56.000000', NULL, 1),
(3105891, 436789, 15711, '<td valign="top">I like the idea and the title.  IT seems a touch harsh in the lighting department. 7</td>', 'I like the idea and the title.  IT seems a touch harsh in the lighting department. 7', '2006-12-11 09:04:59.000000', NULL, 1),
(3105896, 436939, 15711, '<td valign="top">I love this with that hint of color in the sky.  Is it an optical illusion ir is it slightly tilted to the right?</td>', 'I love this with that hint of color in the sky.  Is it an optical illusion ir is it slightly tilted to the right?', '2006-12-11 09:06:07.000000', NULL, 1),
(3105897, 436290, 3102, '<td valign="top">This has been a rather dull challenge to vote on, at least up until this shot!  I love it -- a 10 all the way.  Congrats in advance on the ribbon :)</td>', 'This has been a rather dull challenge to vote on, at least up until this shot!  I love it -- a 10 all the way.  Congrats in advance on the ribbon :)', '2006-12-11 09:06:10.000000', NULL, 1),
(3105899, 436909, 15711, '<td valign="top">I like the expression of pure joy in his face.  This is fun!! 7</td>', 'I like the expression of pure joy in his face.  This is fun!! 7', '2006-12-11 09:06:35.000000', NULL, 1),
(3105903, 436839, 15711, '<td valign="top">Looks like something you''d see in a science textbook, talking about earthworms.</td>', 'Looks like something you''d see in a science textbook, talking about earthworms.', '2006-12-11 09:08:31.000000', NULL, 1),
(3105906, 436836, 15711, '<td valign="top">HEE HEE - cute idea.  That funky mauvy pink background kind of distracts a bit for me. Love the tilt. Good focus. Good DOF. 7</td>', 'HEE HEE - cute idea.  That funky mauvy pink background kind of distracts a bit for me. Love the tilt. Good focus. Good DOF. 7', '2006-12-11 09:09:59.000000', NULL, 1),
(3105908, 436848, 15711, '<td valign="top">Excellent leading line.  I love the saturation of color.  Great perspective on this one. 8</td>', 'Excellent leading line.  I love the saturation of color.  Great perspective on this one. 8', '2006-12-11 09:11:01.000000', NULL, 1),
(3105911, 435606, 15711, '<td valign="top">ha ha ha - you should''ve used a brown duotone. ha ha  Something about this makes me laugh.</td>', 'ha ha ha - you should''ve used a brown duotone. ha ha  Something about this makes me laugh.', '2006-12-11 09:12:11.000000', NULL, 1),
(3105914, 436290, 15711, '<td valign="top">Boy, you really gotta give that kid a great present after this. That is hilarious and the expresison is GREAT!! 7</td>', 'Boy, you really gotta give that kid a great present after this. That is hilarious and the expresison is GREAT!! 7', '2006-12-11 09:12:46.000000', NULL, 1),
