(3106699, 437016, 66384, '<td valign="top">Beautiful landscape. I love the muted colors and the curve of the road.</td>', 'Beautiful landscape. I love the muted colors and the curve of the road.', '2006-12-11 14:59:43.000000', NULL, 1),
(3106710, 436674, 66384, '<td valign="top">More like trash than dirt, but I''ll not quibble over semantics. Whatever you call it, it is a shame that such a beautiful spot of nature is treated this way. Oh, and very nice photo.</td>', 'More like trash than dirt, but I''ll not quibble over semantics. Whatever you call it, it is a shame that such a beautiful spot of nature is treated this way. Oh, and very nice photo.', '2006-12-11 15:02:47.000000', NULL, 1),
(3106722, 436236, 66384, '<td valign="top">Great. Wonderful focus, contrast, and composition. 10</td>', 'Great. Wonderful focus, contrast, and composition. 10', '2006-12-11 15:04:45.000000', NULL, 1),
(3106727, 435606, 66384, '<td valign="top">But not in your face!</td>', 'But not in your face!', '2006-12-11 15:05:21.000000', NULL, 1),
(3106737, 436815, 66384, '<td valign="top">I never imagined that dirt could be so lovely.</td>', 'I never imagined that dirt could be so lovely.', '2006-12-11 15:07:21.000000', NULL, 1),
(3106740, 436178, 40718, '<td valign="top">I sorta wish the DOF went all the way back.  I do like the color in contrast with the blues. 5</td>', 'I sorta wish the DOF went all the way back.  I do like the color in contrast with the blues. 5', '2006-12-11 15:08:07.000000', NULL, 1),
(3106742, 437115, 40718, '<td valign="top">Not bad.  It''s hard to make them look really dirty in a few minutes isn''t it?  At least that''s what I found out. 6</td>', 'Not bad.  It''s hard to make them look really dirty in a few minutes isn''t it?  At least that''s what I found out. 6', '2006-12-11 15:08:52.000000', NULL, 1),
(3106751, 436758, 40718, '<td valign="top">Too much contrast for my taste.  The ring finger is so central in composition and has such a bright highlight compared to the rest of the shot.  Still, it''s creative. 6</td>', 'Too much contrast for my taste.  The ring finger is so central in composition and has such a bright highlight compared to the rest of the shot.  Still, it''s creative. 6', '2006-12-11 15:10:29.000000', NULL, 1),
(3106756, 436067, 66384, '<td valign="top">I''ve often looked at jockeys after a race and thought "what a life!". Good shot. I like the way you framed the face.</td>', 'I''ve often looked at jockeys after a race and thought "what a life!". Good shot. I like the way you framed the face.', '2006-12-11 15:10:51.000000', NULL, 1),
(3106759, 436894, 40718, '<td valign="top">Interesting texture, but I''m not sure I dig it at all. 4</td>', 'Interesting texture, but I''m not sure I dig it at all. 4', '2006-12-11 15:11:23.000000', NULL, 1),
(3106763, 436910, 40718, '<td valign="top">Too bad the upper third is so bright.  I do like the captured blowing sand.  Makes me think about the beach. 5</td>', 'Too bad the upper third is so bright.  I do like the captured blowing sand.  Makes me think about the beach. 5', '2006-12-11 15:12:04.000000', NULL, 1),
(3106765, 436483, 66384, '<td valign="top">Still working on the Death challenge?:) Nice shot. I like the composition.</td>', 'Still working on the Death challenge?:) Nice shot. I like the composition.', '2006-12-11 15:12:50.000000', NULL, 1),
(3106766, 437011, 40718, '<td valign="top">Creative, but to go out of the box on DPC you need a shot that technically is perfect.  This doesn''t cut it. 4</td>', 'Creative, but to go out of the box on DPC you need a shot that technically is perfect.  This doesn''t cut it. 4', '2006-12-11 15:12:56.000000', NULL, 1),
(3106772, 436989, 40718, '<td valign="top">The closed eyes throw me a bit.  I like the composition though, especially the "lean in" of the model on the left.  It looks a bit too "made up", but it isn''t bad. 7</td>', 'The closed eyes throw me a bit.  I like the composition though, especially the "lean in" of the model on the left.  It looks a bit too "made up", but it isn''t bad. 7', '2006-12-11 15:14:13.000000', NULL, 1),
(3106775, 436261, 40718, '<td valign="top">I wonder if a polarizer would have added some saturation to the leaves and dirt?  Fairly static composition. 4</td>', 'I wonder if a polarizer would have added some saturation to the leaves and dirt?  Fairly static composition. 4', '2006-12-11 15:15:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3106776, 436410, 66384, '<td valign="top">I think I would like this better without the sky. The field, ridges, red dirt, and sprouts are great.</td>', 'I think I would like this better without the sky. The field, ridges, red dirt, and sprouts are great.', '2006-12-11 15:15:13.000000', NULL, 1),
(3106780, 436767, 40718, '<td valign="top">I''m not sure if the diagonal composition adds here.  I''d have to see it horizontal as well.  A nice attempt, but just doesn''t rise above anything. 5</td>', 'I''m not sure if the diagonal composition adds here.  I''d have to see it horizontal as well.  A nice attempt, but just doesn''t rise above anything. 5', '2006-12-11 15:15:55.000000', NULL, 1),
(3106784, 435998, 40718, '<td valign="top">The contrast blows a lot of detail here.  The composition is quite centered as well. 4</td>', 'The contrast blows a lot of detail here.  The composition is quite centered as well. 4', '2006-12-11 15:16:43.000000', NULL, 1),
(3106786, 437017, 66384, '<td valign="top">Might be better taken from a different angle. The blue line cuts straight across the center of the shot.</td>', 'Might be better taken from a different angle. The blue line cuts straight across the center of the shot.', '2006-12-11 15:17:21.000000', NULL, 1),
(3106787, 436713, 40718, '<td valign="top">Nice composition.  Not a bad attempt, but this is going to get lost in the host of dirt entries.  There just isn''t quite enough there. 5</td>', 'Nice composition.  Not a bad attempt, but this is going to get lost in the host of dirt entries.  There just isn''t quite enough there. 5', '2006-12-11 15:17:29.000000', NULL, 1),
(3106794, 437086, 40718, '<td valign="top">I can''t think of too much bad to say about it, but I also can''t say that I love it. 6</td>', 'I can''t think of too much bad to say about it, but I also can''t say that I love it. 6', '2006-12-11 15:18:36.000000', NULL, 1),
(3106799, 437109, 40718, '<td valign="top">The color is nice as a contrast.  i think I may have cropped the snake to the bottom of the frame. 6</td>', 'The color is nice as a contrast.  i think I may have cropped the snake to the bottom of the frame. 6', '2006-12-11 15:19:26.000000', NULL, 1),
(3106804, 436350, 40718, '<td valign="top">For some reason she reminds me of Kirsten Dunst.  This is the type of shot I''m digging in this challenge.  REAL dirt, not a bit of applied makeup.  Nice composition.  I like the arm over her head. 8</td>', 'For some reason she reminds me of Kirsten Dunst.  This is the type of shot I''m digging in this challenge.  REAL dirt, not a bit of applied makeup.  Nice composition.  I like the arm over her head. 8', '2006-12-11 15:20:29.000000', NULL, 1),
(3106806, 435849, 66384, '<td valign="top">Very very nice feeling. It seems like the sun is shining on those trees, so I would try bringing that out a little more, maybe by playing with the yellow saturation. 8</td>', 'Very very nice feeling. It seems like the sun is shining on those trees, so I would try bringing that out a little more, maybe by playing with the yellow saturation. 8', '2006-12-11 15:20:54.000000', NULL, 1),
(3106807, 437117, 40718, '<td valign="top">The crop to have the "telephone" on the left is interesting.  That adds something to a picture that was likely pretty uninteresting to start with. 5</td>', 'The crop to have the "telephone" on the left is interesting.  That adds something to a picture that was likely pretty uninteresting to start with. 5', '2006-12-11 15:21:13.000000', NULL, 1),
(3106815, 436791, 66384, '<td valign="top">Mmmm. Looks delicious! Lovely table setting. Nice light and composition. 10</td>', 'Mmmm. Looks delicious! Lovely table setting. Nice light and composition. 10', '2006-12-11 15:23:10.000000', NULL, 1),
(3106816, 436794, 39243, '<td valign="top">Awesome moment! gotta love the chunks/blobs flyin through the air. THe tires look real neat too 9</td>', 'Awesome moment! gotta love the chunks/blobs flyin through the air. THe tires look real neat too 9', '2006-12-11 15:23:26.000000', NULL, 1),
(3106822, 436785, 66384, '<td valign="top">That''s the greenest dirt I have ever seen. Looks like someone spray painted the whole field. Nice horse. Nice light.</td>', 'That''s the greenest dirt I have ever seen. Looks like someone spray painted the whole field. Nice horse. Nice light.', '2006-12-11 15:26:12.000000', NULL, 1),
(3106827, 436985, 53316, '<td valign="top">Doesn''t make sense that the tomatos look like they have just been washed but they are held with dirty hands.</td>', 'Doesn''t make sense that the tomatos look like they have just been washed but they are held with dirty hands.', '2006-12-11 15:27:20.000000', NULL, 1),
(3106828, 437100, 60698, '<td valign="top">Funny, shap focus and nice DOF!  Great expression. What a little trouper! Did this start a dirt fight?? <br/> <br/>The face appears a little dark on my monitor compared to the brighter background. Maybe a bit more light on the face and/or have it angled up slightly to brighten it and show more of her face, although it''s understandable why it''s tilted down. :)</td>', 'Funny, shap focus and nice DOF!  Great expression. What a little trouper! Did this start a dirt fight??  The face appears a little dark on my monitor compared to the brighter background. Maybe a bit more light on the face and/or have it angled up slightly to brighten it and show more of her face, although it''s understandable why it''s tilted down. :)', '2006-12-11 15:27:52.000000', NULL, 1),
(3106832, 435503, 66384, '<td valign="top">Too bad the mask doesn''t look a little muddier. Funny mask face. Good shot.</td>', 'Too bad the mask doesn''t look a little muddier. Funny mask face. Good shot.', '2006-12-11 15:29:11.000000', NULL, 1),
(3106840, 436974, 66384, '<td valign="top">I love all the little pink feet on the dark gray dirt.</td>', 'I love all the little pink feet on the dark gray dirt.', '2006-12-11 15:30:30.000000', NULL, 1),
(3106844, 435756, 66384, '<td valign="top">Yep, that''s what it looks like. Nice composition.</td>', 'Yep, that''s what it looks like. Nice composition.', '2006-12-11 15:31:32.000000', NULL, 1),
(3106849, 436840, 66384, '<td valign="top">Nice. I think the corners were burned a little too much, but this is a lovely landscape.</td>', 'Nice. I think the corners were burned a little too much, but this is a lovely landscape.', '2006-12-11 15:32:50.000000', NULL, 1),
(3106855, 436608, 66384, '<td valign="top">Wash those hands before you come in the house! Well lit, well composed.</td>', 'Wash those hands before you come in the house! Well lit, well composed.', '2006-12-11 15:35:19.000000', NULL, 1),
(3106858, 436028, 66384, '<td valign="top">Strong!</td>', 'Strong!', '2006-12-11 15:36:28.000000', NULL, 1),
(3106866, 437060, 66384, '<td valign="top">Beautiful shot of a terrible thing. Looks like all life on earth will end very soon. 10</td>', 'Beautiful shot of a terrible thing. Looks like all life on earth will end very soon. 10', '2006-12-11 15:38:12.000000', NULL, 1),
(3106872, 436923, 66384, '<td valign="top">Nice horse, nice light, nice action.</td>', 'Nice horse, nice light, nice action.', '2006-12-11 15:39:31.000000', NULL, 1),
