(3107036, 437115, 58728, '<td valign="top">Interesting crop.  I like the color.  The textures stand out wonderfully.</td>', 'Interesting crop.  I like the color.  The textures stand out wonderfully.', '2006-12-11 16:28:49.000000', NULL, 1),
(3107037, 437085, 58728, '<td valign="top">There''s somehting about this shot that I really love. I can''t stop looking at it.  I wonder where they came from, where they are going, where they are...it''s so lonely looking.  I really like the composition.  Great job.</td>', 'There''s somehting about this shot that I really love. I can''t stop looking at it.  I wonder where they came from, where they are going, where they are...it''s so lonely looking.  I really like the composition.  Great job.', '2006-12-11 16:29:34.000000', NULL, 1),
