(3107784, 436122, 5112, '<td valign="top">The hand doesn''t really seem to be in focus here, the picture is just not selling dirt, but "creep", and as creepy pictures go, it isn''t very creepy because of all the clutter in the back.  Nice fence.  ~5</td>', 'The hand doesn''t really seem to be in focus here, the picture is just not selling dirt, but "creep", and as creepy pictures go, it isn''t very creepy because of all the clutter in the back.  Nice fence.  ~5', '2006-12-11 21:15:15.000000', NULL, 1),
(3107787, 435803, 5112, '<td valign="top">It''s not exactly dirt, but it is, nevertheless, a powerful image.  Very sad.  The selective desaturation works well.  Chaos and order at the same time.  ~9</td>', 'It''s not exactly dirt, but it is, nevertheless, a powerful image.  Very sad.  The selective desaturation works well.  Chaos and order at the same time.  ~9', '2006-12-11 21:16:39.000000', NULL, 1),
