(3108902, 436985, 42100, '<td valign="top">Very nice lighting and excellent detail.  The composition is very good as well.  Nicely done!</td>', 'Very nice lighting and excellent detail.  The composition is very good as well.  Nicely done!', '2006-12-12 09:03:47.000000', NULL, 1),
(3108904, 436758, 42100, '<td valign="top">Creative subject and lighting.  Excellent composition that fits the theme perfectly.  Great job!</td>', 'Creative subject and lighting.  Excellent composition that fits the theme perfectly.  Great job!', '2006-12-12 09:04:51.000000', NULL, 1),
(3108905, 436280, 7485, '<td valign="top">A very funny idea, but needs better lighting and context to give it depth. There''s no way to tell what that light colored thing is, and I''m just assuming that the dark stuff is carpet.</td>', 'A very funny idea, but needs better lighting and context to give it depth. There''s no way to tell what that light colored thing is, and I''m just assuming that the dark stuff is carpet.', '2006-12-12 09:05:17.000000', NULL, 1),
(3108906, 436153, 42100, '<td valign="top">Very nice lighting and detail, especially in the eye.  Nicely done!</td>', 'Very nice lighting and detail, especially in the eye.  Nicely done!', '2006-12-12 09:05:34.000000', NULL, 1),
(3108908, 436791, 42100, '<td valign="top">Very sublte on the dirt, but a very effective concept.  Incredible technicals to this photo.  Well done!</td>', 'Very sublte on the dirt, but a very effective concept.  Incredible technicals to this photo.  Well done!', '2006-12-12 09:06:31.000000', NULL, 1),
(3108909, 435652, 42100, '<td valign="top">The subject stands out so boldly against the grungy surroundings.  Very good composition to this.  Great job!</td>', 'The subject stands out so boldly against the grungy surroundings.  Very good composition to this.  Great job!', '2006-12-12 09:07:49.000000', NULL, 1),
