(3108914, 436681, 42100, '<td valign="top">The technicals are excellent in this photo.  So is the creative, but the splotch of blue in the eye seems too unnatural and kind of over the top.</td>', 'The technicals are excellent in this photo.  So is the creative, but the splotch of blue in the eye seems too unnatural and kind of over the top.', '2006-12-12 09:13:49.000000', NULL, 1),
(3108919, 436938, 42100, '<td valign="top">The composition is very good, so are the technicals.  But the qualities seem to get lost in the sea of monochromaticness.</td>', 'The composition is very good, so are the technicals.  But the qualities seem to get lost in the sea of monochromaticness.', '2006-12-12 09:16:21.000000', NULL, 1),
