(3109230, 436713, 62318, '<td valign="top">I like the idea here. I think the execution could have been better. Just not enough going on in the picture for me. Still above average rating.</td>', 'I like the idea here. I think the execution could have been better. Just not enough going on in the picture for me. Still above average rating.', '2006-12-12 13:02:38.000000', NULL, 1),
(3109320, 436774, 40718, '<td valign="top">Make sure to get that picture as big as possible.  You should almost always have 640 pixels on one side.  It''s a cute little shot of a toy.  The lighting is nice and the composition isn''t bad. 6</td>', 'Make sure to get that picture as big as possible.  You should almost always have 640 pixels on one side.  It''s a cute little shot of a toy.  The lighting is nice and the composition isn''t bad. 6', '2006-12-12 13:58:04.000000', NULL, 1),
(3109322, 436974, 40718, '<td valign="top">Did you burn those corners?  A bit distracting actually.  I may have liked a perspective even closer to the ground. 5</td>', 'Did you burn those corners?  A bit distracting actually.  I may have liked a perspective even closer to the ground. 5', '2006-12-12 13:58:50.000000', NULL, 1),
(3109323, 436939, 40718, '<td valign="top">Nicely captured sky.  The textures of the fallow earth aren''t bad.  A nice subtle shot. I wish you were able to bring the barn out a bit in detail. 6</td>', 'Nicely captured sky.  The textures of the fallow earth aren''t bad.  A nice subtle shot. I wish you were able to bring the barn out a bit in detail. 6', '2006-12-12 13:59:40.000000', NULL, 1),
