(3109328, 436911, 40718, '<td valign="top">There isn''t enough subject here.  I know it''s the mountain, but overall the picture is too uniform.  Our eye doesn''t know where to stop.  The overcast or blown sky doesn''t help either. 4</td>', 'There isn''t enough subject here.  I know it''s the mountain, but overall the picture is too uniform.  Our eye doesn''t know where to stop.  The overcast or blown sky doesn''t help either. 4', '2006-12-12 14:01:23.000000', NULL, 1),
(3109330, 437085, 40718, '<td valign="top">A nice rural capture.  I''m not sure if the side of the truck helps or hurts. 6</td>', 'A nice rural capture.  I''m not sure if the side of the truck helps or hurts. 6', '2006-12-12 14:02:00.000000', NULL, 1),
