(3109778, 437015, 40718, '<td valign="top">Well, the spectral highlights on the dirt aren''t helping a lot.  I do like the yellow.  overall it''s a bit too macro for my taste.  I guess I''m not getting to much there, but not a bad shot. 6</td>', 'Well, the spectral highlights on the dirt aren''t helping a lot.  I do like the yellow.  overall it''s a bit too macro for my taste.  I guess I''m not getting to much there, but not a bad shot. 6', '2006-12-12 16:59:17.000000', NULL, 1),
(3109780, 436048, 40718, '<td valign="top">Does work well as an abstract as there is geometry and flow to the image. 7</td>', 'Does work well as an abstract as there is geometry and flow to the image. 7', '2006-12-12 16:59:45.000000', NULL, 1),
(3109781, 436350, 32581, '<td valign="top">fantastic idea</td>', 'fantastic idea', '2006-12-12 17:00:16.000000', NULL, 1),
(3109782, 436890, 66353, '<td valign="top">Nice shot, but I believe I would have liked it more without the HDR treatment. As it is here I''ll give you 6 - a nice "normal" version would probably have earned you a 7.</td>', 'Nice shot, but I believe I would have liked it more without the HDR treatment. As it is here I''ll give you 6 - a nice "normal" version would probably have earned you a 7.', '2006-12-12 17:00:16.000000', NULL, 1),
(3109784, 436989, 66353, '<td valign="top">I''m really glad they are not going to enter my bathtub after the shoot :)<br/>A bit overdone on the mud IMO and the lighting is a little harsh - but still a nice entry.</td>', 'I''m really glad they are not going to enter my bathtub after the shoot :)A bit overdone on the mud IMO and the lighting is a little harsh - but still a nice entry.', '2006-12-12 17:00:38.000000', NULL, 1),
(3109805, 437010, 66353, '<td valign="top">Yea - I hate those spots too - but they sure don''t make much of a picture (But I guess you know that already).</td>', 'Yea - I hate those spots too - but they sure don''t make much of a picture (But I guess you know that already).', '2006-12-12 17:06:08.000000', NULL, 1),
(3109836, 436916, 14614, '<td valign="top">like the B&amp;W but feel the fellow gets lost in the frame with all the bright white items in the background -- a tighter crop (on the right by the far goal post and left to eliminate the far goal posts)and and some darkening to tone down the far goal post on right.  Of course this is only my humble opinion ;)</td>', 'like the B&W but feel the fellow gets lost in the frame with all the bright white items in the background -- a tighter crop (on the right by the far goal post and left to eliminate the far goal posts)and and some darkening to tone down the far goal post on right.  Of course this is only my humble opinion ;)', '2006-12-12 17:16:17.000000', NULL, 1),
(3109840, 436485, 34915, '<td valign="top">Center it more</td>', 'Center it more', '2006-12-12 17:17:10.000000', NULL, 1),
(3109879, 436964, 65234, '<td valign="top">Cute!</td>', 'Cute!', '2006-12-12 17:36:30.000000', NULL, 1),
