(3109891, 436992, 65234, '<td valign="top">Nice leading squiggles.</td>', 'Nice leading squiggles.', '2006-12-12 17:41:47.000000', NULL, 1),
(3109892, 436901, 65234, '<td valign="top">Nice ... no, that''s no really the right word ... creative composition.</td>', 'Nice ... no, that''s no really the right word ... creative composition.', '2006-12-12 17:43:02.000000', NULL, 1),
(3109896, 436796, 65234, '<td valign="top">The dog appears to be laughing hysterically :-)  Could probably crop more of the detail off the right; it distracts from the dog.</td>', 'The dog appears to be laughing hysterically :-)  Could probably crop more of the detail off the right; it distracts from the dog.', '2006-12-12 17:44:54.000000', NULL, 1),
(3109897, 435606, 65234, '<td valign="top">Interesting perspective and good DOF.</td>', 'Interesting perspective and good DOF.', '2006-12-12 17:45:20.000000', NULL, 1),
(3109899, 436828, 65234, '<td valign="top">I''m not sure I like the look in the eye of that cow on the left =:-O  Cool picture.</td>', 'I''m not sure I like the look in the eye of that cow on the left =:-O  Cool picture.', '2006-12-12 17:46:16.000000', NULL, 1),
(3109901, 436890, 65234, '<td valign="top">Very nice contrast between the man and the mannequin.</td>', 'Very nice contrast between the man and the mannequin.', '2006-12-12 17:46:47.000000', NULL, 1),
(3109910, 437117, 65234, '<td valign="top">That red thing on the left looks like a shower head; perhaps someone can rinse him off and put him back together!</td>', 'That red thing on the left looks like a shower head; perhaps someone can rinse him off and put him back together!', '2006-12-12 17:51:28.000000', NULL, 1),
(3109916, 437020, 65234, '<td valign="top">This might have been more effective with the hand/cloth in focus if it''s supposed to be from the camera''s point of view.</td>', 'This might have been more effective with the hand/cloth in focus if it''s supposed to be from the camera''s point of view.', '2006-12-12 17:53:32.000000', NULL, 1),
(3109917, 436356, 57229, '<td valign="top">Funny idea - 7 for that - but it doesn''t look like dirt. (Looks like a picture of dirt, but not like it''s made of dirt:)).</td>', 'Funny idea - 7 for that - but it doesn''t look like dirt. (Looks like a picture of dirt, but not like it''s made of dirt:)).', '2006-12-12 17:54:19.000000', NULL, 1),
(3109919, 437076, 65234, '<td valign="top">Like this composition.</td>', 'Like this composition.', '2006-12-12 17:55:06.000000', NULL, 1),
(3109923, 434805, 57229, '<td valign="top">Interesting effect, but it doesn''t look like mud. (Looks more like gold paint!?!).</td>', 'Interesting effect, but it doesn''t look like mud. (Looks more like gold paint!?!).', '2006-12-12 17:55:58.000000', NULL, 1),
(3109926, 437060, 65234, '<td valign="top">Looks like it''s taking over :-(</td>', 'Looks like it''s taking over :-(', '2006-12-12 17:56:37.000000', NULL, 1),
(3109929, 436153, 65234, '<td valign="top">Interesting expression; glad it''s not aimed at me.</td>', 'Interesting expression; glad it''s not aimed at me.', '2006-12-12 17:57:58.000000', NULL, 1),
(3109931, 436993, 65234, '<td valign="top">Certainly meets the challenge ...</td>', 'Certainly meets the challenge ...', '2006-12-12 17:58:30.000000', NULL, 1),
(3109937, 437006, 65234, '<td valign="top">Don''t know that the title adds much but the shot is cute.  I like the dog watching as if dogs would never do the same!</td>', 'Don''t know that the title adds much but the shot is cute.  I like the dog watching as if dogs would never do the same!', '2006-12-12 18:00:35.000000', NULL, 1),
(3109938, 436458, 57229, '<td valign="top">While most of the pictures have dirt/soil/earth or some such in them, which has been made to look like something else by the post processing, this has (nearly) no dirt at all. I wonder what''s best.</td>', 'While most of the pictures have dirt/soil/earth or some such in them, which has been made to look like something else by the post processing, this has (nearly) no dirt at all. I wonder what''s best.', '2006-12-12 18:00:43.000000', NULL, 1),
(3109939, 436048, 65234, '<td valign="top">Interesting lines and colors.</td>', 'Interesting lines and colors.', '2006-12-12 18:01:03.000000', NULL, 1),
(3109942, 436789, 65234, '<td valign="top">That''s the best he can come up with for his bride?!  They look pretty good, though.  And more practical than flowers ;-)</td>', 'That''s the best he can come up with for his bride?!  They look pretty good, though.  And more practical than flowers ;-)', '2006-12-12 18:02:04.000000', NULL, 1),
(3109943, 436067, 65234, '<td valign="top">Good idea and execution; the title adds a lot to the enjoyment.</td>', 'Good idea and execution; the title adds a lot to the enjoyment.', '2006-12-12 18:03:42.000000', NULL, 1),
(3109949, 436813, 65234, '<td valign="top">I think a dirt trap would be a lint filter or dust cloth or something like that.</td>', 'I think a dirt trap would be a lint filter or dust cloth or something like that.', '2006-12-12 18:05:12.000000', NULL, 1),
(3109950, 437062, 57229, '<td valign="top">Enough dirt but not dirty enough.</td>', 'Enough dirt but not dirty enough.', '2006-12-12 18:06:04.000000', NULL, 1),
(3109953, 436828, 57229, '<td valign="top">LOL</td>', 'LOL', '2006-12-12 18:06:53.000000', NULL, 1),
(3109956, 436458, 65234, '<td valign="top">Lighting is a bit harsh and the angle isn''t interesting to me.</td>', 'Lighting is a bit harsh and the angle isn''t interesting to me.', '2006-12-12 18:07:33.000000', NULL, 1),
(3109958, 436813, 57229, '<td valign="top">This is the first entry I''ve seen that isn''t ''cleaned up''. Bet it bombs. Here''s 9 to help you out.</td>', 'This is the first entry I''ve seen that isn''t ''cleaned up''. Bet it bombs. Here''s 9 to help you out.', '2006-12-12 18:08:56.000000', NULL, 1),
