(3110115, 436985, 15574, '<td valign="top">Very nice, the tomatoes could have been a little redder maybe.</td>', 'Very nice, the tomatoes could have been a little redder maybe.', '2006-12-12 19:14:12.000000', NULL, 1),
(3110118, 436938, 42013, '<td valign="top">Great textures. Just the right amount of green to set off the browns. Good job.</td>', 'Great textures. Just the right amount of green to set off the browns. Good job.', '2006-12-12 19:15:09.000000', NULL, 1),
