INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3110143, 435652, 42013, '<td valign="top">Very well done...it looks a bit like one of Manny''s recent entries. Good luck.</td>', 'Very well done...it looks a bit like one of Manny''s recent entries. Good luck.', '2006-12-12 19:19:18.000000', NULL, 1),
(3110144, 436774, 15574, '<td valign="top">Very fitting title, lol. Would have liked to see it a little bigger though</td>', 'Very fitting title, lol. Would have liked to see it a little bigger though', '2006-12-12 19:19:48.000000', NULL, 1),
(3110154, 437010, 42013, '<td valign="top">I give this a 10 because hopefully you will win a ribbon, win fame and fortune, which will lead to lots of disposable income, a portion of which you will then use to buy a sensor cleaning kit. Good luck! ;)</td>', 'I give this a 10 because hopefully you will win a ribbon, win fame and fortune, which will lead to lots of disposable income, a portion of which you will then use to buy a sensor cleaning kit. Good luck! ;)', '2006-12-12 19:22:41.000000', NULL, 1),
(3110174, 436774, 44086, '<td valign="top">It''s a stationary object. Put your camera on a firm surface and take a longer exposure for better color and focus.</td>', 'It''s a stationary object. Put your camera on a firm surface and take a longer exposure for better color and focus.', '2006-12-12 19:29:17.000000', NULL, 1),
(3110221, 436862, 66267, '<td valign="top">lol</td>', 'lol', '2006-12-12 19:41:47.000000', NULL, 1),
(3110288, 436903, 68343, '<td valign="top">wowo, i really like what uve done with this one. very nice 10</td>', 'wowo, i really like what uve done with this one. very nice 10', '2006-12-12 20:00:27.000000', NULL, 1),
(3110302, 436772, 58430, '<td valign="top">This is hilarious!  Love it.  Love the title and the goggles and the expression. Something seems a touch off with the PP.  The dirt in the bangs seem fake.  Not sure what it is.</td>', 'This is hilarious!  Love it.  Love the title and the goggles and the expression. Something seems a touch off with the PP.  The dirt in the bangs seem fake.  Not sure what it is.', '2006-12-12 20:04:33.000000', NULL, 1),
(3110306, 436263, 58430, '<td valign="top">Great PP.  Love the colors.</td>', 'Great PP.  Love the colors.', '2006-12-12 20:05:29.000000', NULL, 1),
(3110342, 436263, 23484, '<td valign="top">Really nice shot. I really like the post processing in this.9</td>', 'Really nice shot. I really like the post processing in this.9', '2006-12-12 20:25:31.000000', NULL, 1),
(3110350, 436410, 23484, '<td valign="top">This is a beautiful shot.  The only thing I don''t like is the grass in front.  I think it really detracts from it. The leading lines are great. 8</td>', 'This is a beautiful shot.  The only thing I don''t like is the grass in front.  I think it really detracts from it. The leading lines are great. 8', '2006-12-12 20:27:16.000000', NULL, 1),
(3110359, 436772, 23484, '<td valign="top">Excellent job.  I really like the processing on this. 8</td>', 'Excellent job.  I really like the processing on this. 8', '2006-12-12 20:30:52.000000', NULL, 1),
(3110360, 436236, 23484, '<td valign="top">Great detail.  I''m not a cat fan but I really like this shot. 7</td>', 'Great detail.  I''m not a cat fan but I really like this shot. 7', '2006-12-12 20:31:42.000000', NULL, 1),
(3110362, 437008, 65234, '<td valign="top">OK, different kind of dirt but nicely done.</td>', 'OK, different kind of dirt but nicely done.', '2006-12-12 20:31:50.000000', NULL, 1),
(3110364, 435548, 23484, '<td valign="top">I love this.  There are two distinct parts to this shot. Very fine and very gritty.  Good job. 9</td>', 'I love this.  There are two distinct parts to this shot. Very fine and very gritty.  Good job. 9', '2006-12-12 20:33:38.000000', NULL, 1),
(3110367, 437010, 23484, '<td valign="top">I can certainly relate to this.  I''ll bet you have a lot of comments saying the same thing.</td>', 'I can certainly relate to this.  I''ll bet you have a lot of comments saying the same thing.', '2006-12-12 20:36:01.000000', NULL, 1),
(3110368, 436791, 65234, '<td valign="top">OMG, on the nice china and everything ... ewwwwww!!  I really hope that''s just chocolate-something, but I can''t find a harmless interpretation for the worms.  Oh, and photographically, the only real flaw is that the entire piece of pie is not in sharp focus and probably should have been.  9, anyway, for thoroughly grossing me out.</td>', 'OMG, on the nice china and everything ... ewwwwww!!  I really hope that''s just chocolate-something, but I can''t find a harmless interpretation for the worms.  Oh, and photographically, the only real flaw is that the entire piece of pie is not in sharp focus and probably should have been.  9, anyway, for thoroughly grossing me out.', '2006-12-12 20:36:03.000000', NULL, 1),
(3110371, 436828, 23484, '<td valign="top">Excellent shot. 8</td>', 'Excellent shot. 8', '2006-12-12 20:36:46.000000', NULL, 1),
(3110374, 435414, 65234, '<td valign="top">Very nice job on maintaining the differentiation between the &lt;insert adjective here&gt;''s hair and the dirt in which he is mostly buried.</td>', 'Very nice job on maintaining the differentiation between the <insert adjective here>''s hair and the dirt in which he is mostly buried.', '2006-12-12 20:38:41.000000', NULL, 1),
(3110377, 436432, 65234, '<td valign="top">Like the idea; would prefer the sky toned down a bit to emphasize the boy more.</td>', 'Like the idea; would prefer the sky toned down a bit to emphasize the boy more.', '2006-12-12 20:43:04.000000', NULL, 1),
(3110380, 436890, 23484, '<td valign="top">Great job.  I like the whole composition and the grittiness. 8</td>', 'Great job.  I like the whole composition and the grittiness. 8', '2006-12-12 20:43:37.000000', NULL, 1),
(3110384, 436290, 65234, '<td valign="top">And not looking too thrilled about the photo op ;-)</td>', 'And not looking too thrilled about the photo op ;-)', '2006-12-12 20:44:56.000000', NULL, 1),
(3110386, 436985, 23484, '<td valign="top">Nice shot.  You should hang this on your kitchen wall. 8</td>', 'Nice shot.  You should hang this on your kitchen wall. 8', '2006-12-12 20:45:55.000000', NULL, 1),
(3110387, 436629, 65234, '<td valign="top">Aww!  I like the dirt on the window, too.  Mine look like that a lot!  I''d try editing the pupils to get the greenish cast out.</td>', 'Aww!  I like the dirt on the window, too.  Mine look like that a lot!  I''d try editing the pupils to get the greenish cast out.', '2006-12-12 20:46:35.000000', NULL, 1),
(3110394, 436839, 65234, '<td valign="top">Well composed.</td>', 'Well composed.', '2006-12-12 20:49:39.000000', NULL, 1),
(3110420, 436989, 48876, '<td valign="top">Great Picture! I just wish they all had their eye''s open.</td>', 'Great Picture! I just wish they all had their eye''s open.', '2006-12-12 21:02:57.000000', NULL, 1),
(3110467, 437005, 48876, '<td valign="top">I really like this one, it draws you in!</td>', 'I really like this one, it draws you in!', '2006-12-12 21:24:02.000000', NULL, 1),
(3110490, 435169, 69008, '<td valign="top">Nice textures and composition. Good dirt.</td>', 'Nice textures and composition. Good dirt.', '2006-12-12 21:30:32.000000', NULL, 1),
(3110503, 436903, 69008, '<td valign="top">Looks a lot like my hands at work. I build and rebuild machinery for veg packing plants. It''s really difficult to clean it out from under your nails if you get dirty daily like this. The thumb nail needs some under it. Good lighting, good subject, fits the challenge theme.</td>', 'Looks a lot like my hands at work. I build and rebuild machinery for veg packing plants. It''s really difficult to clean it out from under your nails if you get dirty daily like this. The thumb nail needs some under it. Good lighting, good subject, fits the challenge theme.', '2006-12-12 21:35:43.000000', NULL, 1),
(3110509, 436894, 69008, '<td valign="top">Dirt Filter! I''ve been wanting one for Christmas! (like a polarizer, except it gives this effect) <br/>Except for the vehicles, this looks like a pic taken in a coal mining town in the 1930''s. Gritty looking place with the subdued light.</td>', 'Dirt Filter! I''ve been wanting one for Christmas! (like a polarizer, except it gives this effect) Except for the vehicles, this looks like a pic taken in a coal mining town in the 1930''s. Gritty looking place with the subdued light.', '2006-12-12 21:43:52.000000', NULL, 1),
(3110515, 437055, 69008, '<td valign="top">The world is an unfair place. Good subject. The strong sunlight is a problem, but no way to control that when shooting on the run outdoors. The whole scene is necessary to complete the story.</td>', 'The world is an unfair place. Good subject. The strong sunlight is a problem, but no way to control that when shooting on the run outdoors. The whole scene is necessary to complete the story.', '2006-12-12 21:48:47.000000', NULL, 1),
(3110536, 436939, 15574, '<td valign="top">I love the darkness, some might say it''s underexposed but I think it''s perfect.</td>', 'I love the darkness, some might say it''s underexposed but I think it''s perfect.', '2006-12-12 21:58:16.000000', NULL, 1),
(3110547, 436458, 69008, '<td valign="top">These things are indestructable here in Florida. There''s one big as a car in my yard.  <br/>I don''t know what to say about the picture. It seems to have no story to tell. The whole frame seems busy, but not  tugging my attention to any one point. I shot a lot of pics like this, and for a long time. I do get one that redeems the rest once in a while though. Keep clicking away and the magic pictures will happen someday without you even realizing it.</td>', 'These things are indestructable here in Florida. There''s one big as a car in my yard.  I don''t know what to say about the picture. It seems to have no story to tell. The whole frame seems busy, but not  tugging my attention to any one point. I shot a lot of pics like this, and for a long time. I do get one that redeems the rest once in a while though. Keep clicking away and the magic pictures will happen someday without you even realizing it.', '2006-12-12 22:01:47.000000', NULL, 1),
(3110562, 437005, 69008, '<td valign="top">Offer her a towel and a beer!  This girl looks like she''s been having a good time at the mud hole.  Good use of extra large aperture for shallow depth of field. Good in B&amp;W too. Color would reset the attention even more on the eyes and away from the dirt.</td>', 'Offer her a towel and a beer!  This girl looks like she''s been having a good time at the mud hole.  Good use of extra large aperture for shallow depth of field. Good in B&W too. Color would reset the attention even more on the eyes and away from the dirt.', '2006-12-12 22:07:42.000000', NULL, 1),
(3110564, 437086, 69008, '<td valign="top">Now that''s mixing dirt with pleasure. I like the action, the subdued color, and the subject. The dust adds seasoning as well. The fence is sort of not good, but happiness is where you find it, so it still gets a good rating.</td>', 'Now that''s mixing dirt with pleasure. I like the action, the subdued color, and the subject. The dust adds seasoning as well. The fence is sort of not good, but happiness is where you find it, so it still gets a good rating.', '2006-12-12 22:07:51.000000', NULL, 1),
(3110573, 437116, 2170, '<td valign="top">i hate to say it, but it kinda looks like poop.</td>', 'i hate to say it, but it kinda looks like poop.', '2006-12-12 22:10:06.000000', NULL, 1),
(3110579, 436736, 69008, '<td valign="top">The dirt looks like fertilizer. The nail tells a story with an unhappy ending.</td>', 'The dirt looks like fertilizer. The nail tells a story with an unhappy ending.', '2006-12-12 22:13:17.000000', NULL, 1),
(3110585, 436350, 69008, '<td valign="top">Nice idea, posing the arm to frame the face works for this composition.</td>', 'Nice idea, posing the arm to frame the face works for this composition.', '2006-12-12 22:16:02.000000', NULL, 1),
(3110599, 436989, 60698, '<td valign="top">Wow factor alert! Love the effort you put into this. Great lighting and PP. Nice how the girl in the middle seems to support the other two, showing great strength. Timeless and a real work of art.</td>', 'Wow factor alert! Love the effort you put into this. Great lighting and PP. Nice how the girl in the middle seems to support the other two, showing great strength. Timeless and a real work of art.', '2006-12-12 22:20:44.000000', NULL, 1),
(3110600, 436828, 60698, '<td valign="top">Holy cow!! What''s going on here? Fantastic image and point of view! Want to know more. Should be a print for sure!</td>', 'Holy cow!! What''s going on here? Fantastic image and point of view! Want to know more. Should be a print for sure!', '2006-12-12 22:20:46.000000', NULL, 1),
(3110601, 437085, 69008, '<td valign="top">Not much of big interest in this pic. I can see why you would want to keep rolling. It''s much better than streets lined with housing developments though.</td>', 'Not much of big interest in this pic. I can see why you would want to keep rolling. It''s much better than streets lined with housing developments though.', '2006-12-12 22:21:08.000000', NULL, 1),
(3110603, 436791, 60698, '<td valign="top">Well done in every way!!</td>', 'Well done in every way!!', '2006-12-12 22:21:32.000000', NULL, 1),
(3110605, 436772, 37104, '<td valign="top">Fantastic!! My pick of the litter.</td>', 'Fantastic!! My pick of the litter.', '2006-12-12 22:22:52.000000', NULL, 1),
(3110606, 435606, 2170, '<td valign="top">i love this.  love love love this.</td>', 'i love this.  love love love this.', '2006-12-12 22:23:00.000000', NULL, 1),
(3110609, 436772, 2170, '<td valign="top">this is really really well done.  love it.</td>', 'this is really really well done.  love it.', '2006-12-12 22:24:14.000000', NULL, 1),
