(3115485, 436955, 69008, '<td valign="top">Fine duck pic. Feathers make good pics. Beautiful, well focused . A little overexposed on the neck. My experience with birds with white on them is that it helps to reduce exposure by at least -1 stop, or the white gets washed completely out.</td>', 'Fine duck pic. Feathers make good pics. Beautiful, well focused . A little overexposed on the neck. My experience with birds with white on them is that it helps to reduce exposure by at least -1 stop, or the white gets washed completely out.', '2006-12-13 22:11:58.000000', NULL, 1),
(3115497, 435756, 52115, '<td valign="top">It''s supposed to be dirt, I see a wagon or something, there, I''ll believe it''s really dirt-n-snow.</td>', 'It''s supposed to be dirt, I see a wagon or something, there, I''ll believe it''s really dirt-n-snow.', '2006-12-13 22:13:45.000000', NULL, 1),
