(3117504, 436067, 67258, '<td valign="top">Very good!</td>', 'Very good!', '2006-12-14 13:42:21.000000', NULL, 1),
(3117508, 436862, 67258, '<td valign="top">Ummm - why?</td>', 'Ummm - why?', '2006-12-14 13:44:46.000000', NULL, 1),
