(3117515, 436350, 67258, '<td valign="top">Very well composed - in fact well executed all round.</td>', 'Very well composed - in fact well executed all round.', '2006-12-14 13:47:16.000000', NULL, 1),
(3117521, 434836, 67258, '<td valign="top">I like the styling, and the concept.</td>', 'I like the styling, and the concept.', '2006-12-14 13:49:27.000000', NULL, 1),
(3117524, 436048, 67258, '<td valign="top">I like the basic shot, but find the contrast, and perhaps the sharpening, a little too much.</td>', 'I like the basic shot, but find the contrast, and perhaps the sharpening, a little too much.', '2006-12-14 13:50:20.000000', NULL, 1),
(3117525, 436772, 67258, '<td valign="top">LOL!</td>', 'LOL!', '2006-12-14 13:51:00.000000', NULL, 1),
(3117674, 435652, 24073, '<td valign="top">Too young to be this provocative, and seductive.  It distracts me, and only for the reason mentioned, I would vote 9+ if the model was a shade older.  Still a fantastic image that sits very high in the challenge.  GL.</td>', 'Too young to be this provocative, and seductive.  It distracts me, and only for the reason mentioned, I would vote 9+ if the model was a shade older.  Still a fantastic image that sits very high in the challenge.  GL.', '2006-12-14 15:14:05.000000', NULL, 1),
(3117815, 436894, 53316, '<td valign="top">One of my absolute favorites in the challenge.</td>', 'One of my absolute favorites in the challenge.', '2006-12-14 16:19:32.000000', NULL, 1),
