(3125772, 436943, 9906, '<td valign="top">You are quite underexposed with this shot.  There is not enough detail left in the dirt and this is quite distracting.<br/>TC</td>', 'You are quite underexposed with this shot.  There is not enough detail left in the dirt and this is quite distracting.TC', '2006-12-17 14:00:44.000000', NULL, 1),
(3125775, 434836, 10818, '<td valign="top">There are alot of dirty faces, but I really like this because it appears quite genuine.</td>', 'There are alot of dirty faces, but I really like this because it appears quite genuine.', '2006-12-17 14:01:49.000000', NULL, 1),
(3125777, 437100, 9906, '<td valign="top">Did you use the flash for this?  It could use quite a bit more light on the subjects to both stop the action and to make the subject ''fit in'' with the brightness of the background.<br/>TC</td>', 'Did you use the flash for this?  It could use quite a bit more light on the subjects to both stop the action and to make the subject ''fit in'' with the brightness of the background.TC', '2006-12-17 14:02:11.000000', NULL, 1),
(3125782, 437092, 9906, '<td valign="top">Very cute!  Makes me wonder if there''s a story here.  I am wondering why you chose b/w for this though...<br/>TC</td>', 'Very cute!  Makes me wonder if there''s a story here.  I am wondering why you chose b/w for this though...TC', '2006-12-17 14:03:28.000000', NULL, 1),
(3125783, 436740, 9906, '<td valign="top">and very dark...  There''s just enough background detail to distract from the overall subject of the shot.  Needs to be lighter in the background to pull out more detail or darker in the background to eliminate the distractions...<br/>TC</td>', 'and very dark...  There''s just enough background detail to distract from the overall subject of the shot.  Needs to be lighter in the background to pull out more detail or darker in the background to eliminate the distractions...TC', '2006-12-17 14:04:43.000000', NULL, 1),
(3125786, 436993, 9906, '<td valign="top">I''m sorry but the dirt by itself is not a strong enough subject to hold the eye...<br/>TC</td>', 'I''m sorry but the dirt by itself is not a strong enough subject to hold the eye...TC', '2006-12-17 14:05:12.000000', NULL, 1),
(3125802, 437011, 9906, '<td valign="top">Certainly a dirty phone...  :-P<br/>TC</td>', 'Certainly a dirty phone...  :-PTC', '2006-12-17 14:18:39.000000', NULL, 1),
(3125805, 437087, 9906, '<td valign="top">Very subtle.  Love the simplicity!  Can almost smell the dirt!<br/>TC</td>', 'Very subtle.  Love the simplicity!  Can almost smell the dirt!TC', '2006-12-17 14:22:17.000000', NULL, 1),
